//! 🧪️ Actual three paged identities preserve Unicode semantics and original custody across paid assembly and cancellation.
use super::*;
use crate::HybridLogicalTimestamp;
use semio_framework_value::{retirement::RetireOwned,retained_clone::RetainedCloneSource};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[derive(semio_framework_value::RetireOwned)]
struct Authority{actor:Text}
impl ArtifactCanonicalEditAuthority for Authority{fn sequence_number(&self)->i32{1}fn clock(&self)->HybridLogicalTimestamp{HybridLogicalTimestamp{actor:1,physical_ms:1,logical:1}}fn actor(&self)->&(dyn Utf8Text+Sync){&self.actor}fn line(&self)->Option<&(dyn Utf8Text+Sync)>{None}fn group(&self)->Option<&(dyn Utf8Text+Sync)>{None}}
fn grant(demand:RetirementDemand)->RetainedCloneGrant{assert!(demand.copy_bytes+demand.capacity_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth}}
fn source<T:RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{let birth=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let admitted=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:birth.capacity_bytes,maximum_depth:birth.depth,..Default::default()};let((source,progress),heap)=observe(||RetainedCloneSource::admit_owned(value,(),admitted).unwrap_or_else(|(error,_,_)|panic!("native semantic source: {error}")));assert!(progress.fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));source}
fn close<T:RetireOwned+Sync>(source:&mut RetainedCloneSource<T>){for turn in 0..100000{if source.terminal_is_empty(){return;}let work=source.next_close_copy_byte_demand().unwrap();let admitted=grant(RetirementDemand{copy_bytes:work,capacity_bytes:source.next_close_capacity_byte_demand(work).unwrap(),release_bytes:source.next_close_release_byte_demand().unwrap(),depth:source.next_close_depth_demand().unwrap()});let(step,heap)=observe(||source.close_step(admitted).unwrap());assert!(step.progress().fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(turn<99999||source.terminal_is_empty());}}

#[test]
fn canonical_native_identity_assembly_preserves_original_unicode_fields_and_exact_granted_cancellation(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../../🛍️products/💻️os/🔨️modules/🏪️store/📦️prepared/🪪️identity/🧫️fixtures/🔣️.json")).unwrap();
 for repeats in [1,fixture["repeat"].as_u64().unwrap()as usize]{for pause in [Some(0),Some(1),Some(3),Some(17),Some(129),None]{
  let actor=fixture["actor"].as_str().unwrap().repeat(repeats);let id=fixture["id"].as_str().unwrap();let native=Authority{actor:actor.as_str().into()};let actor_pointer=native.actor.chunks().next().unwrap().as_ptr();let mut authority=source(native);
  let mut edit=Box::new(Edit::<bool>{id:id.to_owned(),actor:None,line:None,sequence_number:1,forwards:vec![true],mutation_meta:Vec::new(),inverse:crate::value::list::PagedList::new(),verb:None,started_at:String::new(),finished_at:None});edit.id.reserve(8192);let edit_pointer=edit.as_ref()as*const Edit<bool>;let id_pointer=edit.id.as_ptr();let mut edit=source(edit);
  let((original_authority,original_edit),heap)=observe(||(authority.project_owned(0,|value|value as&dyn ArtifactCanonicalEditAuthority),edit.project_owned(0,|value|value.as_ref())));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  let admitted=grant(ArtifactCanonicalEditIdentityCursor::<bool>::constructor_demand());let((mut cursor,receipt),heap)=observe(||ArtifactCanonicalEditIdentityCursor::admit(original_authority,original_edit,admitted).unwrap_or_else(|_|panic!("identity original admission")));assert!(receipt.fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut turns=0;
  while !cursor.terminal_is_empty()&&!cursor.is_ready(){assert!(turns<100000);if pause==Some(turns){cursor.begin_close();}let(demand,heap)=observe(||cursor.next_demand().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let admitted=grant(demand);
   for refused in [RetainedCloneGrant::default(),RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..admitted}]{if refused==admitted{continue;}let(step,heap)=observe(||cursor.advance(refused).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
   let(step,heap)=observe(||cursor.advance(admitted).unwrap());assert!(step.progress().fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;
  }
  if cursor.is_ready(){assert!(pause.is_none_or(|cut|cut>=turns));let original_pointers=cursor.output.as_ref().unwrap().each_ref().map(|value|value.chunks().next().unwrap().as_ptr());let admitted=grant(cursor.next_take_demand());let(take,heap)=observe(||cursor.take(RetainedCloneGrant::default()).unwrap());assert!(take.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let((output,receipt),heap)=observe(||cursor.take(admitted).unwrap().unwrap());assert!(receipt.fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(output.each_ref().map(|value|value.chunks().next().unwrap().as_ptr()),original_pointers);assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::json!([actor,id,id]));let[a,b,c]=output;let mut output=source((a,b,c));close(&mut output);let(_,heap)=observe(||drop(output));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  assert!(cursor.terminal_is_empty());assert_eq!(authority.borrow().get().actor.chunks().next().unwrap().as_ptr(),actor_pointer);assert_eq!(edit.borrow().get().as_ref()as*const Edit<bool>,edit_pointer);assert_eq!(edit.borrow().get().id.as_ptr(),id_pointer);let(_,heap)=observe(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close(&mut edit);close(&mut authority);let(_,heap)=observe(||{drop(edit);drop(authority);});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  println!("[DEBUG] native paged identity repeats={repeats} pause={pause:?} turns={turns}; same original actor/Edit/id pointers, real output pages match shared SQLite/JSON, exact zero/below/full4096 heap receipts, cursor/output/source terminalDrop0");
 }}
}
